def count_hexagons(N):
    total_sum = 0
    for a in range(-N, N + 1):
        for b in range(-N, N + 1):
            c = -a - b
            if -N <= c <= N:
                if a == 0 and b == 0 and c == 0:
                    continue
                M = max(abs(a), abs(b), abs(c))
                if M <= N:
                    K = N - M
                    total_sum += 3 * K**2 + 3 * K + 1
    return total_sum // 6

for N in range(1, 6):
    print(f"N={N}: {count_hexagons(N)}")

def count_hexagons_of_side_L(N, L):
    count = 0
    for a in range(-N, N + 1):
        for b in range(-N, N + 1):
            c = -a - b
            if -N <= c <= N:
                if a == 0 and b == 0 and c == 0:
                    continue
                if a**2 + b**2 + c**2 == 2 * L**2:
                    M = max(abs(a), abs(b), abs(c))
                    if M <= N:
                        K = N - M
                        count += 3 * K**2 + 3 * K + 1
    return count // 6

for L in range(1, 8):
    print(f"L={L}, N=10: {count_hexagons_of_side_L(10, L)}")

